+    }
+    case "num":
+      return <span className={`${VAL} font-mono text-[var(--accent-blue)]`}>{String(value)}</span>;
+    case "date": {
+      const display = formatDate(value as string | Date);
+      const rel = formatRelativeDate(value as string | Date);
+      return (
+        <span className={`${VAL} tabular-nums`}>
