+              >
+                {stringify(item)}
+              </span>
+            ))}
+          </span>
+        </span>
+      );
+    }
+    case "link": {
+      const href = value as string;
+      const external = isExternalHref(href);
+      return (
+        <span className={VAL}>
+          <a
+            href={href}
+            className="text-[var(--link)] hover:underline"
+            {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
+          >
+            {href}
+          </a>
